# diagnostics class
p=Path("app/src/main/java/ru/kazna/app/DiagnosticLog.java")
p.write_text('package ru.kazna.app;\n\nimport android.content.*;\nimport android.content.pm.*;\nimport android.os.*;\nimport java.io.*;\nimport java.nio.charset.StandardCharsets;\nimport java.time.*;\nimport java.time.format.DateTimeFormatter;\nimport java.util.*;\n\n/** Local privacy-aware diagnostic journal and human-readable support report. */\npublic final class DiagnosticLog {\n private static final Object LOCK=new Object();\n private static final String FILE="kazna-diagnostic.log";\n private static final int MAX_LINES=200;\n private DiagnosticLog(){}\n\n public static void log(Context c,String area,String message){\n  if(c==null)return;String line=Instant.now().toString()+" | "+safe(area)+" | "+safe(message)+"\\n";\n  synchronized(LOCK){try{File f=new File(c.getFilesDir(),FILE);try(FileOutputStream out=new FileOutputStream(f,true)){out.write(line.getBytes(StandardCharsets.UTF_8));}trim(f);}catch(Exception ignored){}}\n }\n public static void error(Context c,String area,Throwable ex){String m=ex==null?"unknown":ex.getClass().getSimpleName()+(ex.getMessage()==null?"":" · "+ex.getMessage());log(c,area,"ERROR · "+m);}\n private static String safe(String s){if(s==null)return "";String x=s.replace(\'\\n\',\' \').replace(\'\\r\',\' \').replaceAll("\\\\s+"," ").trim();x=x.replaceAll("(?<!\\\\d)(\\\\d{8,24})(?!\\\\d)","••••");return x.length()>500?x.substring(0,500)+"…":x;}\n private static void trim(File f)throws IOException{List<String> lines=new ArrayList<>();try(BufferedReader r=new BufferedReader(new InputStreamReader(new FileInputStream(f),StandardCharsets.UTF_8))){String s;while((s=r.readLine())!=null)lines.add(s);}int from=Math.max(0,lines.size()-MAX_LINES);if(from==0&&f.length()<256*1024)return;try(BufferedWriter w=new BufferedWriter(new OutputStreamWriter(new FileOutputStream(f,false),StandardCharsets.UTF_8))){for(int i=from;i<lines.size();i++){w.write(lines.get(i));w.newLine();}}}\n private static String card(String s){if(s==null||s.isEmpty())return "—";return "••"+s.substring(Math.max(0,s.length()-4));}\n private static String money(long k){return String.format(Locale.US,"%.2f RUB",k/100.0);}\n private static String version(Context c){try{PackageInfo p=c.getPackageManager().getPackageInfo(c.getPackageName(),0);return p.versionName+" ("+(Build.VERSION.SDK_INT>=28?p.getLongVersionCode():p.versionCode)+")";}catch(Exception ex){return "unknown";}}\n private static List<String> lines(Context c){List<String> out=new ArrayList<>();File f=new File(c.getFilesDir(),FILE);if(!f.exists())return out;try(BufferedReader r=new BufferedReader(new InputStreamReader(new FileInputStream(f),StandardCharsets.UTF_8))){String s;while((s=r.readLine())!=null)out.add(s);}catch(Exception ignored){}return out;}\n public static String report(Context c){\n  StringBuilder b=new StringBuilder(16384);SharedPreferences p=c.getSharedPreferences("kazna",0);Store store=Store.get(c);\n  b.append("KAZNA DIAGNOSTIC REPORT\\n");b.append("Created: ").append(Instant.now()).append(\'\\n\');b.append("App: ").append(version(c)).append(\'\\n\');b.append("Android: ").append(Build.VERSION.RELEASE).append(" / SDK ").append(Build.VERSION.SDK_INT).append(\'\\n\');b.append("Device: ").append(Build.MANUFACTURER).append(\' \').append(Build.MODEL).append(\'\\n\');b.append("Mode: ").append(p.getString("mode","off")).append(\'\\n\');b.append("Notification listener: ").append(SmsNotificationService.connected?"connected":"not connected").append(\'\\n\');\n  long seen=p.getLong("push_seen",0);if(seen>0)b.append("Last push: ").append(Instant.ofEpochMilli(seen)).append(" · ").append(safe(p.getString("push_bank",""))).append(" · ").append(safe(p.getString("push_result",""))).append(\'\\n\');\n  long test=p.getLong("push_test_seen",0);if(test>0)b.append("Last push test: ").append(Instant.ofEpochMilli(test)).append(" · ").append(safe(p.getString("push_test_result",""))).append(\'\\n\');\n  b.append("\\nACCOUNTS\\n");for(Store.Account a:store.accounts())b.append("- ").append(a.bank).append(\' \').append(card(a.card)).append(" · ").append(a.kind).append(" · balance=").append(a.hasBalance?money(a.balance):"unknown").append(" · source=").append(safe(a.source)).append(\'\\n\');\n  b.append("\\nDEBTS\\n");for(Store.Debt d:store.debts())b.append("- ").append(safe(d.bank)).append(" · ").append(safe(d.kind)).append(" · debt=").append(money(d.debt)).append(" · principal=").append(money(d.principalDebt)).append(" · interest=").append(money(d.interestDebt)).append(" · payment=").append(money(d.monthlyPayment)).append(" · term=").append(d.termMonths).append("m · remaining=").append(d.remainingMonths).append("m\\n");\n  b.append("\\nRECENT OPERATIONS (max 30, raw bank texts excluded)\\n");List<Entry> es=store.all();int n=Math.min(30,es.size());for(int i=0;i<n;i++){Entry e=es.get(i);b.append("- ").append(Instant.ofEpochMilli(e.time)).append(" · ").append(e.bank).append(\' \').append(card(e.card)).append(" · ").append(e.type).append(" · ").append(money(e.amount)).append(" · ").append(safe(e.category)).append(" · source=").append(safe(e.source)).append(e.review?" · REVIEW":"").append(\'\\n\');}\n  b.append("\\nEVENT LOG (last ").append(MAX_LINES).append(")\\n");for(String s:lines(c))b.append(safe(s)).append(\'\\n\');\n  b.append("\\nPRIVACY\\nFull notification texts, statement contents, passwords, full card/account numbers and OCR image data are intentionally not included.\\n");return b.toString();\n }\n public static void clear(Context c){synchronized(LOCK){try{new File(c.getFilesDir(),FILE).delete();}catch(Exception ignored){}}log(c,"DIAG","Журнал очищен");}\n}\n')

